contract InvMutTest {
    C c;
    constructor() { c = new C(); }
    function __ESBMC_reverted() internal returns (bool) {}
    function __ESBMC_assume(bool) internal pure {}

    function run(address target) public payable {
        bool probeOk;
        c.sendMoney(target, 0); bool __rev0 = __ESBMC_reverted(); if (__rev0) { probeOk = false; } else { probeOk = true; }

        uint balBefore = address(c).balance;
        uint countBefore = c.depositsCount(); if (__ESBMC_reverted()) return;

        bool reverted;
        c.sendMoney(target, 0); bool __rev1 = __ESBMC_reverted(); if (__rev1) { reverted = true; } else { reverted = false; }

        uint balAfter = address(c).balance;
        uint countAfter = c.depositsCount(); if (__ESBMC_reverted()) return;

        assert(probeOk == !reverted && balAfter == balBefore && countAfter == countBefore);
    }

    receive() external payable {}
}

